import{_ as i,C as n,o as l,c as s,ah as r,E as o,j as a,a as e}from"./chunks/framework.DuX8SFU5.js";const m=JSON.parse('{"title":"AM_CAN_LOGGER — руководство пользователя","description":"","frontmatter":{},"headers":[],"relativePath":"am_can_logger/user-guide.md","filePath":"am_can_logger/user-guide.md"}'),_={name:"am_can_logger/user-guide.md"};function c(h,t,g,A,p,u){const d=n("AssetImage");return l(),s("div",null,[t[0]||(t[0]=r('<h1 id="am-can-logger-—-руководство-пользователя" tabindex="-1">AM_CAN_LOGGER — руководство пользователя <a class="header-anchor" href="#am-can-logger-—-руководство-пользователя" aria-label="Permalink to &quot;AM_CAN_LOGGER — руководство пользователя&quot;">​</a></h1><h2 id="состав-комплекта" tabindex="-1">Состав комплекта <a class="header-anchor" href="#состав-комплекта" aria-label="Permalink to &quot;Состав комплекта&quot;">​</a></h2><p>В комплект входят:</p><ul><li>Контроллер <a href="https://docs.px4.io/main/en/assembly/quick_start_cuav_pixhawk_v6x" target="_blank" rel="noreferrer">CUAV Pixhawk V6X</a> с прошивкой AM_CAN_LOGGER.</li><li>Два кабеля для подключения к CAN-шинам станка: CAN_H, CAN_L и GND.</li><li>Wi-Fi-модуль <a href="https://store.cuav.net/cuav-pw-link-docs-tutorial-firmware-troubleshooting/" target="_blank" rel="noreferrer">CUAV PW-Link</a>, подключённый к порту TELEM1.</li><li>Преобразователь DC/DC для питания регистратора от бортовой сети станка.</li><li>USB-кабель для подключения к компьютеру.</li><li>Набор наклеек двустороннего скотча для крепления контроллера к раме станка.</li><li>USB-HUB с ETH и кардридером для микро SD карты</li></ul>',4)),o(d,{name:"am_can_logger_kit.webp",alt:"Комплект AM_CAN_LOGGER: контроллер, два кабеля CAN, модуль PW-Link, преобразователь питания и USB-кабель"}),t[1]||(t[1]=a("p",null,"Наклейки двустороннего скотча на фотографии не показаны.",-1)),t[2]||(t[2]=a("h3",{id:"разъемы-и-распиновка",tabindex:"-1"},[e("Разъёмы и распиновка "),a("a",{class:"header-anchor",href:"#разъемы-и-распиновка","aria-label":'Permalink to "Разъёмы и распиновка"'},"​")],-1)),t[3]||(t[3]=a("p",null,[e("PW-Link подключается к TELEM1, преобразователь питания — к POWER C1, кабели шин станка — к CAN1 и CAN2. Нумерация контактов приведена по "),a("a",{href:"https://docs.px4.io/main/en/assembly/quick_start_cuav_pixhawk_v6x#pinouts",target:"_blank",rel:"noreferrer"},"схеме разъёмов CUAV Pixhawk V6X"),e(". Перед подключением сверяйте положение контакта 1 со схемой: при взгляде на ответную часть кабеля расположение контактов зеркальное.")],-1)),o(d,{name:"am_can_logger_pixhawk_v6x_pinout.webp",alt:"Распиновка разъёмов CUAV Pixhawk V6X, включая TELEM1, POWER C1, CAN1 и CAN2"}),t[4]||(t[4]=r('<table tabindex="0"><thead><tr><th>Контакт</th><th>TELEM1</th><th>POWER C1</th><th>CAN1</th><th>CAN2</th></tr></thead><tbody><tr><td>1</td><td>+5 В</td><td>+5 В, вход питания</td><td>+5 В</td><td>+5 В</td></tr><tr><td>2</td><td>TX, передача от контроллера</td><td>+5 В, вход питания</td><td>CAN1_H</td><td>CAN2_H</td></tr><tr><td>3</td><td>RX, приём контроллером</td><td>CAN_H модуля питания</td><td>CAN1_L</td><td>CAN2_L</td></tr><tr><td>4</td><td>CTS, управление потоком</td><td>CAN_L модуля питания</td><td>GND</td><td>GND</td></tr><tr><td>5</td><td>RTS, управление потоком</td><td>GND</td><td>—</td><td>—</td></tr><tr><td>6</td><td>GND</td><td>GND</td><td>—</td><td>—</td></tr></tbody></table><p>Для PW-Link используются питание +5 В, GND и линии UART: TX контроллера соединяется с RX модуля, RX контроллера — с TX модуля. К сети станка подключаются только CAN_H, CAN_L и GND; контакт +5 В разъёмов CAN1 и CAN2 к сети станка не подключается. Питание от бортовой сети подаётся через комплектный DC/DC-преобразователь; подавать бортовое напряжение напрямую на POWER C1 нельзя.</p><h2 id="подключение-к-сети-станка" tabindex="-1">Подключение к сети станка <a class="header-anchor" href="#подключение-к-сети-станка" aria-label="Permalink to &quot;Подключение к сети станка&quot;">​</a></h2><h2 id="включение" tabindex="-1">Включение <a class="header-anchor" href="#включение" aria-label="Permalink to &quot;Включение&quot;">​</a></h2><h2 id="подключение-к-дэшборду" tabindex="-1">Подключение к дэшборду <a class="header-anchor" href="#подключение-к-дэшборду" aria-label="Permalink to &quot;Подключение к дэшборду&quot;">​</a></h2><p>Дэшборд работает через приложение <strong>AM CAN logger tools</strong>: оно запускает серверную часть на компьютере или телефоне и показывает данные регистратора. Сначала скачайте приложение для своей системы, затем подключитесь к регистратору и запустите его. Устанавливать Python отдельно не требуется.</p><h3 id="скачать-приложение" tabindex="-1">Скачать приложение <a class="header-anchor" href="#скачать-приложение" aria-label="Permalink to &quot;Скачать приложение&quot;">​</a></h3><p>За актуальными файлами приложения обратитесь к разработчику.</p><p>Для описанного ниже порядка работы используется сборка <strong>v0.5.0</strong> от <strong>8 октября 2026 года</strong>, коммит <strong>9761e5ac</strong>. В сообщении со сборкой она обозначена как <code>AM CAN logger tools v0.5.0: Linux AppImage, Windows app, Android app</code> и <code>DEV BUILD • main</code>, базовый тег — <code>v0.5.0</code>. Скачайте один файл для своей системы:</p><table tabindex="0"><thead><tr><th>Система</th><th>Файл</th><th>Подготовка к запуску</th></tr></thead><tbody><tr><td>Windows 10 и новее, x64</td><td><code>am_canlog-v0.5.0-windows-x64.exe</code></td><td>Сохраните EXE на компьютере; установка не требуется.</td></tr><tr><td>Linux, x86-64</td><td><code>am_canlog-v0.5.0-linux-x64.AppImage</code></td><td>Разрешите выполнение файла как программы в его свойствах.</td></tr><tr><td>Android 7 и новее, ARM64</td><td><code>am_canlog-v0.5.0-android.apk</code></td><td>Откройте APK и установите приложение; при запросе разрешите установку из выбранного источника.</td></tr></tbody></table><p>Скачайте файл заранее: точка доступа PW-Link служит для связи с регистратором и не предоставляет доступ в интернет.</p><h3 id="выбрать-подключение-wi-fi-или-usb" tabindex="-1">Выбрать подключение: Wi-Fi или USB <a class="header-anchor" href="#выбрать-подключение-wi-fi-или-usb" aria-label="Permalink to &quot;Выбрать подключение: Wi-Fi или USB&quot;">​</a></h3><p>После включения питания регистратора подключённый к TELEM1 модуль PW-Link создаёт точку доступа Wi-Fi. Находясь рядом с устройством, откройте список сетей на компьютере или телефоне и найдите имя вида <code>CUAVWLink_XXXXXX</code>. Окончание имени отличается у каждого модуля; на примере ниже видны два PW-Link, поэтому при наличии нескольких устройств выбирайте сеть нужного регистратора. Пароль по умолчанию — <code>cuavwlink</code>, если он не был изменён при подготовке комплекта (<a href="https://store.cuav.net/cuav-pw-link-docs-tutorial-firmware-troubleshooting/" target="_blank" rel="noreferrer">документация CUAV</a>). Дождитесь подключения к сети; если система предупреждает об отсутствии интернета, выберите сохранение подключения к этой сети.</p>',13)),o(d,{name:"am_can_logger_pwlink_wifi.webp",alt:"Пример сетей CUAVWLink в списке Wi-Fi Windows: выбран модуль CUAVWLink_e68fa3"}),t[5]||(t[5]=r('<p>На компьютере вместо Wi-Fi можно подключить регистратор комплектным USB-кабелем. Для приложения Android в этом руководстве используется подключение по Wi-Fi. После выбора Wi-Fi или USB порядок работы с дэшбордом одинаков: запустите приложение и проверьте подключение в верхней панели. При работе по USB закройте QGroundControl и другие программы, которые могут занимать порт регистратора.</p><h3 id="запустить-приложение" tabindex="-1">Запустить приложение <a class="header-anchor" href="#запустить-приложение" aria-label="Permalink to &quot;Запустить приложение&quot;">​</a></h3><p>В Windows дважды щёлкните <code>am_canlog-v0.5.0-windows-x64.exe</code>; в Linux запустите <code>am_canlog-v0.5.0-linux-x64.AppImage</code>. Приложение запускает локальный сервер и автоматически открывает страницу дэшборда в браузере. Если вкладка не появилась, откройте <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a> на том же компьютере. На Android откройте установленное приложение <strong>AM CAN logger</strong>: дэшборд появится внутри приложения.</p><p>На компьютере при первом запуске режим <code>auto</code> выбирает подключённый по USB регистратор, а при его отсутствии — Wi-Fi через UDP, порт 14550. При следующих запусках приложение использует ранее выбранное подключение. Если данные не появляются, нажмите на индикатор подключения рядом с названием дэшборда и выберите <code>auto</code>, нужный USB-порт или UDP для Wi-Fi. При первом запросе брандмауэра Windows разрешите приложению сетевой доступ: он необходим для получения данных через PW-Link.</p><p>В Windows сервер работает как фоновый процесс и не имеет отдельного окна. Чтобы найти его, откройте диспетчер задач сочетанием <code>Ctrl+Shift+Esc</code>, перейдите в «Процессы» и введите <code>am_canlog</code> в поиск. На примере ниже имя файла отличается от версии в таблице, но процесс узнаётся по началу <code>am_canlog</code>.</p>',5)),o(d,{name:"am_can_logger_task_manager.webp",alt:"AM CAN logger в фоновых процессах диспетчера задач Windows; сверху доступна кнопка «Завершить задачу»"}),t[6]||(t[6]=a("p",null,[e("Для обычного завершения используйте кнопку "),a("code",null,"Quit"),e(" в дэшборде; локальное приложение также останавливается при закрытии последней вкладки панели. При необходимости процесс можно остановить через диспетчер задач: выберите "),a("code",null,"am_canlog"),e(" и нажмите «Завершить задачу». После остановки сервера локальная панель недоступна, но регистратор продолжает автономную запись при наличии питания.")],-1)),t[7]||(t[7]=a("h3",{id:"что-отображается-в-дэшборде",tabindex:"-1"},[e("Что отображается в дэшборде "),a("a",{class:"header-anchor",href:"#что-отображается-в-дэшборде","aria-label":'Permalink to "Что отображается в дэшборде"'},"​")],-1)),t[8]||(t[8]=a("p",null,[e("После установления связи появятся список записей и текущие показания регистратора. На скриншоте показано подключение по USB: индикатор "),a("code",null,"auto · COM5"),e(" в верхней панели. Номер COM-порта на другом компьютере может отличаться.")],-1)),o(d,{name:"am_can_logger_user_guide_dashboard.webp",alt:"Дэшборд AM CAN logger v0.5.0: верхняя строка состояния, список записей слева и графики текущих показаний справа"}),t[9]||(t[9]=r('<ul><li><strong>Верхняя панель:</strong> название и версия приложения, выбранное подключение, число подключённых клиентов, поток кадров и данных, загрузка CPU регистратора, свободное место на карте памяти; справа — кнопки доступа к публикации панели и настройкам.</li><li><strong>Слева — записи:</strong> вкладка <code>On the card</code> показывает сессии на карте регистратора, <code>On this computer</code> — сохранённые на компьютере; для сессий видны время, объём и отметки событий, а текущая запись помечена <code>recording</code>.</li><li><strong>Справа — текущие показания LIVE:</strong> во вкладке <code>Charts</code> отображаются загрузка CAN1 и CAN2, поток записи на SD-карту и вибрации; кнопки <code>2 min</code>, <code>10 min</code>, <code>30 min</code> выбирают интервал графиков, кнопка паузы приостанавливает их обновление.</li><li><strong>Над графиками:</strong> поле <code>Event marker</code> и кнопка <code>Mark</code> для фиксации событий; рядом с <code>Charts</code> находится вкладка <code>Sniffer</code> для просмотра CAN-трафика.</li></ul><p>Подробное описание элементов — в <a href="./dashboard">руководстве по панели</a>.</p><h2 id="проверка-работы-и-хода-записи" tabindex="-1">Проверка работы и хода записи <a class="header-anchor" href="#проверка-работы-и-хода-записи" aria-label="Permalink to &quot;Проверка работы и хода записи&quot;">​</a></h2><h2 id="фиксация-событии-через-дэшборд" tabindex="-1">Фиксация событий через дэшборд <a class="header-anchor" href="#фиксация-событии-через-дэшборд" aria-label="Permalink to &quot;Фиксация событий через дэшборд&quot;">​</a></h2>',4))])}const b=i(_,[["render",c]]);export{m as __pageData,b as default};
